#!/usr/bin/env bash
# Clean up caches generated by the Mojo compiler.
#
# Mojo caches compiled code so unchanged programs are not recompiled. The
# cache is safe to delete: Mojo rebuilds it, the next builds are just slower.
# Clearing it also makes compile-time code (and compile-time print) run again.
#
# Usage: ./compcache_cleanup.sh [options]
#
#   (no options)   Delete the Mojo compile cache:
#                    ${XDG_CACHE_HOME:-~/.cache}/modular/.mojo_cache
#                  plus ~/.cache/modular/.mojo_cache if XDG_CACHE_HOME
#                  points elsewhere, and temporary caches left behind by
#                  'build.sh --no-cache' runs that were interrupted.
#   --modular      Delete the whole modular cache folder instead
#                  (${XDG_CACHE_HOME:-~/.cache}/modular), including any
#                  caches other Modular tools (e.g. MAX) put there.
#   -n, --dry-run  Only print what would be deleted.
#   -h, --help     Show this help.

set -uo pipefail

usage() { sed -n '2,/^$/{s/^# \{0,1\}//;p}' "${BASH_SOURCE[0]}"; }

whole_modular=false
dry=false

while (($#)); do
    case "$1" in
        --modular) whole_modular=true ;;
        -n|--dry-run) dry=true ;;
        -h|--help) usage; exit 0 ;;
        *) echo "error: unknown option: $1" >&2; usage >&2; exit 1 ;;
    esac
    shift
done

remove() {
    local size
    size="$(du -sh -- "$1" 2>/dev/null | cut -f1)"
    if $dry; then
        echo "would remove: $1 (${size:-?})"
    else
        echo "removing: $1 (${size:-?})"
        rm -rf -- "$1"
    fi
}

# Cache roots: the active one and the default one, without duplicates.
roots=("${XDG_CACHE_HOME:-$HOME/.cache}")
[[ "${roots[0]}" != "$HOME/.cache" ]] && roots+=("$HOME/.cache")

targets=()
for r in "${roots[@]}"; do
    if $whole_modular; then
        targets+=("$r/modular")
    else
        targets+=("$r/modular/.mojo_cache")
    fi
done

# Leftover temporary caches from interrupted 'build.sh --no-cache' runs.
while IFS= read -r d; do
    targets+=("$d")
done < <(find "${TMPDIR:-/tmp}" -maxdepth 1 -type d -name 'mojo-nocache.*' -user "$(id -u)" 2>/dev/null)

found=false
for t in "${targets[@]}"; do
    if [[ -e "$t" ]]; then
        found=true
        remove "$t"
    fi
done

$found || echo "No Mojo compile caches found."
exit 0
